using System;using System.IO;using System.Linq;using System.Text;using UnityEditor;using UnityEngine;using UnityEngine.SceneManagement;
public static class ClassroomWallProbe {
 [InitializeOnLoadMethod]static void Init(){if(File.Exists("Library/classroom-wall-probe.request"))EditorApplication.delayCall+=Run;}
 static void Run(){try{File.Delete("Library/classroom-wall-probe.request");Physics.SyncTransforms();var p=new[]{new Vector3(487.75f,0,35),new Vector3(510.5f,0,35),new Vector3(489.5f,0,16.25f),new Vector3(490,0,1.25f),new Vector3(514.75f,0,-12.5f)};var s=new StringBuilder();for(int i=0;i<p.Length;i++){s.AppendLine("DESK "+i+" "+p[i]);foreach(var dir in new[]{Vector3.left,Vector3.right,Vector3.forward,Vector3.back}){var hit=Physics.RaycastAll(p[i]+Vector3.up*1.85f,dir,12,Physics.DefaultRaycastLayers,QueryTriggerInteraction.Ignore).OrderBy(h=>h.distance).FirstOrDefault(h=>h.collider.name.StartsWith("School Structure"));if(hit.collider)s.AppendLine("DIR "+dir+" "+hit.collider.name+" point="+hit.point.ToString("F2")+" normal="+hit.normal.ToString("F2")+" dist="+hit.distance.ToString("F2"));}}File.WriteAllText("Tools/classroom-wall-probe.txt",s.ToString());}catch(Exception e){File.WriteAllText("Tools/classroom-wall-probe.txt","FAIL "+e);Debug.LogException(e);}}
}
